<?php
namespace Tplix;
/**
 *  Tags: handle the Tags
 */
class Tags
{
    /**
     * Validates the token stream to ensure all opening tags have corresponding closing tags.
     *
     * @param array $tokens The token stream generated by tokenize().
     * @return array Returns an array of error messages if mismatched tags are found, otherwise an empty array.
     */
    public static function validate(array $tokens): array
    {
        $errors = [];
        $stack = []; // Stack to hold expected closing tags and their line numbers
        $startTagMap = [
            "IF_START" => "IF_END",
            //"ELSEIF_START" => "ELSEIF_END",
            //"FORELSEIF_START" => "FORELSEIF_END",
            "WITH_START" => "WITH_END",
            "FOREACH_START" => "FOREACH_END",
            "FOR_START" => "FOR_END",
            "LOOP_START" => "LOOP_END",
            "LITERAL_START" => "LITERAL_END",
            "CAPTURE_START"=>"CAPTURE_END",
            "WHILE_START"=>"WHILE_END",
            "BLOCK_START"=>"BLOCK_END",
            "CAPTURE_START"=>"CAPTURE_END",
            "DYNAMIC_START"=>"DYNAMIC_END",
            "NOCACHE_START"=>"NOCACHE_END",
            "TEMPLATE_START"=>"TEMPLATE_END",
            "TEXTFORMAT_START"=>"TEXTFORMAT_END",
            "DYNAMIC_START"=>"DYNAMIC_END",
            "EXTENDS_START"=>"EXTENDS_END",
            "STRIP_START"=>"STRIP_END",            
        ];
        foreach ($tokens as $index => $token)
        {
            $type = $token['type'];
            // Check if it's a start tag
            if (isset($startTagMap[$type]))
            {
                $expectedEndType = $startTagMap[$type];
                $stack[] = [
                    'expected' => $expectedEndType,
                    'line' => $token['line'],
                    'name' => $token['name'], // e.g., 'if', 'foreach'
                    'index' => $index
                ];
            }
            // Check if it's an end tag
            elseif (in_array($type, $startTagMap) && !isset($token["linkedTo"])) { // Check if $type is one of the values in $startTagMap (i.e., an END type)
                if (empty($stack)) {
                    $closingTag = "{/".strtolower(str_replace("_END","",$type))."}";
                    // Found an end tag without a matching start tag
                    $errors[] = "Unexpected closing tag '{$closingTag}' (line {$token['line']}, token index {$index}).";
                } else {
                    $expectedTag = array_pop($stack);
                    if ($expectedTag['expected'] !== $type) {
                        // Mismatched tags
                        $closingTag = "{/".strtolower(str_replace("_END","",$expectedTag['expected']))."}";
                        $errors[] = "Mismatched tag: expected '{$closingTag}' for opening '{$expectedTag['name']}' (line {$expectedTag['line']}, token index {$expectedTag['index']}) but found '{$type}' (line {$token['line']}, token index {$index}).";
                    }
                }
            }
        }
        // After processing all tokens, check if any tags were left unclosed
        if (!empty($stack))
        {
            foreach ($stack as $unclosedTag)
            {
                $closingTag = "{/".strtolower(str_replace("_END","",$unclosedTag['expected']))."}";
                $errors[] = "Unclosed tag '{$unclosedTag['name']}' (started on line {$unclosedTag['line']}, token index {$unclosedTag['index']}). Expected '{$closingTag}'.";
            }
        }
        return $errors;
    }  
}